import openpyxl
wb=openpyxl.load_workbook('/root/data/workbook.xlsx', data_only=False)
ws=wb['Data']
# find cells with 2018..2022
targets={2018,2019,2020,2021,2022,'2018','2019','2020','2021','2022'}
found=[]
for row in ws.iter_rows(values_only=False):
    for cell in row:
        v=cell.value
        if v in targets:
            found.append((cell.coordinate,v))
print('Found year cells:', found[:50])
print('Total found:', len(found))
# also try find any string containing '2018'
